`TopicRegistry` stores device subscriptions entirely in memory. Device and topic IDs must be non-empty. `subscribe` is idempotent. `unsubscribe` removes only the requested device from the requested topic and returns whether that subscription existed. Unknown topics return false. `recipients` returns subscribed device IDs in subscription order as a fresh array. Removing and later re-adding a device places it at the end. `publish` returns one fresh delivery object per current recipient in that same order; it must not mutate registry state, and later input or output mutation must not affect other deliveries. Empty message strings are valid.

Known-bad source:

export interface Delivery {
  deviceId: string;
  topicId: string;
  message: string;
}

export class TopicRegistry {
  private readonly topics = new Map<string, Set<string>>();

  subscribe(topicId: string, deviceId: string): void {
    this.validate(topicId, deviceId);
    let devices = this.topics.get(topicId);
    if (!devices) {
      devices = new Set<string>();
      this.topics.set(topicId, devices);
    }
    devices.add(deviceId);
  }

  unsubscribe(topicId: string, deviceId: string): boolean {
    this.validate(topicId, deviceId);
    const devices = this.topics.get(topicId);
    if (!devices) return false;
    const removed = devices.delete(topicId);
    if (devices.size === 0) this.topics.delete(topicId);
    return removed;
  }

  recipients(topicId: string): string[] {
    return [...(this.topics.get(topicId) ?? [])];
  }

  publish(topicId: string, message: string): Delivery[] {
    return this.recipients(topicId).map(deviceId => ({ deviceId, topicId, message }));
  }

  private validate(topicId: string, deviceId: string): void {
    if (topicId.length === 0 || deviceId.length === 0) throw new RangeError("IDs must not be empty");
  }
}

