import { TopicRegistry } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function throws(action: () => unknown, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

const registry = new TopicRegistry();
throws(() => registry.subscribe('', 'device'), 'empty topic');
throws(() => registry.subscribe('topic', ''), 'empty device');
throws(() => registry.unsubscribe('', 'device'), 'unsubscribe validates topic');

registry.subscribe('news', 'd1');
registry.subscribe('news', 'd2');
registry.subscribe('news', 'd1');
equal(registry.recipients('news'), ['d1', 'd2'], 'subscription order and idempotence');

const recipients = registry.recipients('news');
recipients.push('fake');
equal(registry.recipients('news'), ['d1', 'd2'], 'recipient array must be fresh');
assert(registry.recipients('unknown').length === 0, 'unknown recipients');

assert(registry.unsubscribe('unknown', 'd1') === false, 'unknown topic unsubscribe');
assert(registry.unsubscribe('news', 'd1') === true, 'existing unsubscribe');
equal(registry.recipients('news'), ['d2'], 'only requested device removed');
assert(registry.unsubscribe('news', 'd1') === false, 'already removed subscription');
registry.subscribe('news', 'd1');
equal(registry.recipients('news'), ['d2', 'd1'], 're-added device moves to end');

const deliveries = registry.publish('news', '');
equal(deliveries, [
  { deviceId: 'd2', topicId: 'news', message: '' },
  { deviceId: 'd1', topicId: 'news', message: '' }
], 'publishing empty message in recipient order');
assert(deliveries[0] !== deliveries[1], 'delivery objects must be distinct');
deliveries[0].deviceId = 'changed';
deliveries[0].message = 'changed';
equal(registry.publish('news', ''), [
  { deviceId: 'd2', topicId: 'news', message: '' },
  { deviceId: 'd1', topicId: 'news', message: '' }
], 'delivery mutation must not affect registry or later deliveries');

assert(registry.unsubscribe('news', 'd2') === true, 'remove penultimate subscription');
assert(registry.unsubscribe('news', 'd1') === true, 'remove final subscription');
assert(registry.recipients('news').length === 0, 'empty topic cleanup');

